export function TabNav(a,t){return`\n        <div class="isro-tab-nav" role="tablist" aria-label="ISRO Explorer Sections">\n            <div class="isro-tab-scroll">\n                ${a.map(a=>{const n=a.id===t;return`<button class="isro-tab-btn ${n?"active":""}" data-tab="${a.id}" aria-selected="${n}" role="tab">${a.label}</button>`}).join("")}\n            </div>\n        </div>\n    `}